const item = $input.first().json;

const mensagem = String(item.body?.mensagem ?? '').trim();

// Detecta mensagens compostas exclusivamente por emoji.
// Inclui emojis com modificadores de pele, combinações com ZWJ,
// corações, bandeiras etc.
const emojiOnlyRegex =
  /^(?:\p{Extended_Pictographic}|\p{Regional_Indicator}|\p{Emoji_Modifier}|\uFE0F|\u200D|\s)+$/u;

const somenteEmoji =
  mensagem.length > 0 &&
  emojiOnlyRegex.test(mensagem);

return [
  {
    json: {
      ...item,

      bia_gate: {
        precisa_responder: !somenteEmoji,
        motivo: somenteEmoji
          ? 'reacao_emoji_isolada'
          : 'mensagem_com_conteudo'
      }
    }
  }
];

const item = $input.first().json;

const output = String(item.output ?? '').trim();

const regrasProibidas = [
  {
    motivo: 'consulta_contexto',
    regex: /\bconsulta\s+(?:ao|do)\s+contexto\b/i
  },
  {
    motivo: 'nome_ferramenta_contexto',
    regex: /consultar_contexto(?:_bna)?/i
  },
  {
    motivo: 'system_message',
    regex: /\bsystem\s*message\b/i
  },
  {
    motivo: 'workflow',
    regex: /\bworkflow\b/i
  },
  {
    motivo: 'tool',
    regex: /\btool\b/i
  },
  {
    motivo: 'prompt',
    regex: /\bprompt\b/i
  },
  {
    motivo: 'chamada_ferramenta',
    regex: /\bchamada\s+de\s+ferramenta\b/i
  },
  {
    motivo: 'processo_interno',
    regex: /\bprocessos?\s+internos?\b/i
  },
  {
    motivo: 'regra_interna',
    regex: /\bregras?\s+internas?\b/i
  },
  {
    motivo: 'base_nao_trouxe',
    regex: /\b(?:a\s+)?base\s+(?:não\s+)?(?:trouxe|retornou|indicou|encontrou)\b/i
  },
  {
    motivo: 'nenhuma_regra',
    regex: /\b(?:nenhuma|não\s+(?:há|existe|encontrei))\s+regra\b/i
  },
  {
    motivo: 'crm',
    regex: /\bCRM\b/i
  },
  {
    motivo: 'banco_dados',
    regex: /\bbanco\s+de\s+dados\b/i
  },
  {
    motivo: 'automacao_interna',
    regex: /\bautomaç(?:ão|oes|ões)\b/i
  }
];

const motivosEncontrados = regrasProibidas
  .filter(regra => regra.regex.test(output))
  .map(regra => regra.motivo);

const temConteudoInterno = motivosEncontrados.length > 0;
const respostaVazia = output.length === 0;

const saidaSegura = !temConteudoInterno && !respostaVazia;

return [
  {
    json: {
      ...item,

      bia_guard: {
        segura: saidaSegura,
        bloqueada: !saidaSegura,
        motivos: motivosEncontrados,
        resposta_vazia: respostaVazia
      },

      // Mantemos isso apenas para diagnóstico dentro do n8n.
      // Nunca deve ser enviado ao cliente.
      output_original_bloqueado: !saidaSegura ? output : ''
    }
  }
];

